// Expresión para obtener el ID desde la URL guardada:
const url = $json.url_archivo;
const match = url.match(/\/d\/([a-zA-Z0-9_-]+)/);
const fileId = match ? match[1] : url; // Devuelve el fileId extraído
return { fileId };

// Este nodo recibe el resultado de la búsqueda de la carpeta del cliente
const inputItem = $input.first();
const datosCliente = $('Al ejecutar el flujo').first().json;

let folderId = null;

// Verificamos si el nodo de Google Drive anterior encontró la carpeta
if (inputItem && inputItem.json && inputItem.json.id) {
    folderId = inputItem.json.id;
} else {
    // Si no existe, aquí puedes retornar una bandera para que el siguiente nodo la cree,
    // o manejar el ID de la carpeta raíz por defecto ("DOCUMENTOS CLIENTES")
    folderId = "1HSbo5MVioo_OIDhaK48BcXbM78yRC8it"; // ID de tu carpeta raíz por defecto
}

return [{
    json: {
        folderId: folderId,
        pasaporte_nie: datosCliente.pasaporte_nie,
        nombre_cliente: datosCliente.nombre_cliente,
        nombre_documento: datosCliente.nombre_documento,
        url_archivo: datosCliente.url_archivo
    }
}];

// Captura la URL o ID del archivo y el nombre provenientes del nodo anterior
const url = $json.url_archivo || "";
const nombreArchivo = $json.name || $json.nombre_documento || "";

// Extrae el ID de la URL mediante Regex
const match = url.match(/\/d\/([a-zA-Z0-9_-]+)/);
const fileId = match ? match[1] : url;

// Retorna un objeto con ambos datos
return {
  fileId: fileId,
  nombreArchivo: nombreArchivo
};

